@layer theme, base, components, utilities;

/* Shared text utilities; other components compose these classes. */

/* The fade only shows when text overflows: otherwise the scroll timeline is inactive. */

@property --truncate-fade {
  syntax: "<length>";
  inherits: false;
  initial-value: 0px;
}

@layer components {
  /* Text that's never cut: a long name, email or path breaks onto the next
     line, inside a word only when there's nowhere else to break. Use this for
     anything a person needs to read in full. */
  .wrap {
    min-width: 0;
    overflow-wrap: anywhere;
    text-wrap: pretty;
  }

  /* One line, fading at the end when cut. Only for rows that must keep a
     fixed height (a virtualized table); give the full text a title too. The padding/negative margin stops
     overflow: hidden clipping descenders and accents at tight line heights. */
  .truncate {
    min-width: 0;
    overflow: hidden;
    white-space: nowrap;
    padding-block: 0.2em;
    margin-block: -0.2em;
  }

  /* Several lines; set --truncate-lines (default 2). */
  .truncateLines {
    overflow: hidden;
    max-height: calc(var(--truncate-lines, 2) * 1lh);
  }

  @supports (animation-timeline: scroll()) {
    .truncate,
    .truncateLines {
      --truncate-to: right;
      animation: truncate-overflow linear both;
    }

    :is([dir="rtl"]) .truncate,
    :is([dir="rtl"]) .truncateLines {
      --truncate-to: left;
    }

    .truncate {
      mask-image: linear-gradient(to var(--truncate-to), #000 calc(100% - var(--truncate-fade)), transparent);
      animation-timeline: scroll(self inline);
    }

    .truncateLines {
      mask-image:
        linear-gradient(#000 0 0),
        linear-gradient(to var(--truncate-to), #000 calc(100% - var(--truncate-fade)), transparent);
      mask-size: 100% calc(100% - 1lh), 100% 1lh;
      mask-position: top, bottom;
      mask-repeat: no-repeat;
      animation-timeline: scroll(self block);
    }
  }

  /* Without scroll timelines, fall back to an ellipsis. */
  @supports not (animation-timeline: scroll()) {
    .truncate {
      text-overflow: ellipsis;
    }

    .truncateLines {
      display: -webkit-box;
      -webkit-box-orient: vertical;
      -webkit-line-clamp: var(--truncate-lines, 2);
    }
  }

  @keyframes truncate-overflow {
    from,
    to {
      --truncate-fade: 24px;
    }
  }

  /* Visually hidden, still read by screen readers. */
  .srOnly {
    position: absolute;
    width: 1px;
    height: 1px;
    overflow: hidden;
    clip-path: inset(50%);
    white-space: nowrap;
  }

  /* Work in progress: a light band sweeps across dimmed text. --sweep-dim sets the dim. */
  .sweep {
    mask-image: linear-gradient(
      90deg,
      rgb(0 0 0 / var(--sweep-dim, 0.55)) 35%,
      #000 50%,
      rgb(0 0 0 / var(--sweep-dim, 0.55)) 65%
    );
    mask-size: 300% 100%;
    mask-repeat: no-repeat;
    animation: sweep var(--ui-dur-sweep) linear infinite;
  }

  @keyframes sweep {
    from {
      mask-position: 100% 0;
    }
    to {
      mask-position: 0 0;
    }
  }

  @media (prefers-reduced-motion: reduce) {
    .sweep {
      mask-image: none;
      animation: none;
    }
  }
}

@layer theme, base, components, utilities;

/* The real label, for screen readers and find-in-page. */
.label {
  composes: srOnly from "../text/text.module.css";
}

/* Block padding keeps descenders inside the mask. */
@property --morph-fade {
  syntax: "<length>";
  inherits: false;
  initial-value: 0px;
}

@layer components {
  .root {
    position: relative;
    display: inline-flex;
    white-space: pre;
  }

  .row {
    --morph-to: right;
    position: relative;
    display: inline-flex;
    padding-block: 0.3em;
    margin-block: -0.3em;
  }

  :is([dir="rtl"]) .row {
    --morph-to: left;
  }

  .row[data-morphing] {
    mask-image: linear-gradient(to var(--morph-to), #000 calc(100% - var(--morph-fade)), transparent);
  }

  /* A filter (the blur on arriving and leaving letters) paints only inside
     the element's box, and a glyph's descender hangs below a tight line box.
     The block padding grows each letter's box to hold its descenders; the
     negative margin gives the room back, so nothing moves. */
  .glyph {
    display: inline-block;
    padding-block: 0.3em;
    margin-block: -0.3em;
  }

  .ghosts {
    position: absolute;
    inset: 0;
    pointer-events: none;
  }

  /* Sits where the letter sat: the row's block padding, held as the ghost's
     own padding so its blur has room for descenders too. */
  .ghost {
    position: absolute;
    top: 0;
    padding-block: 0.3em;
  }
}

"use client";

import { useLayoutEffect, useRef, useState } from "react";
import styles from "./text-morph.module.css";

type Glyph = { key: string; char: string };
type Layout = { text: string; glyphs: Glyph[]; lefts: Map<string, number>; width: number };

const segmenter =
  typeof Intl !== "undefined" && "Segmenter" in Intl
    ? new Intl.Segmenter(undefined, { granularity: "grapheme" })
    : null;

function split(text: string) {
  return segmenter ? Array.from(segmenter.segment(text), (s) => s.segment) : Array.from(text);
}

type Word = { start: number; end: number; text: string };

function words(chars: string[]): Word[] {
  const out: Word[] = [];
  let start = -1;
  chars.forEach((c, i) => {
    const space = /\s/.test(c);
    if (!space && start === -1) start = i;
    if (space && start !== -1) {
      out.push({ start, end: i, text: chars.slice(start, i).join("").toLowerCase() });
      start = -1;
    }
  });
  if (start !== -1) out.push({ start, end: chars.length, text: chars.slice(start).join("").toLowerCase() });
  return out;
}

/** Shared start and end letters: "Copy" → "Copied" keeps "Cop". */
function edges(a: string[], b: string[]): [number, number][] {
  const pairs: [number, number][] = [];
  let start = 0;
  while (start < a.length && start < b.length && a[start] === b[start]) pairs.push([start, start++]);
  for (let k = 1; k <= Math.min(a.length, b.length) - start && a[a.length - k] === b[b.length - k]; k++) {
    pairs.push([a.length - k, b.length - k]);
  }
  return pairs;
}

/** Keys letters, reusing old keys for shared words and gap edges so they slide. */
function toGlyphs(prev: Glyph[] | null, text: string, generation: number): Glyph[] {
  // Same keys on the server and in the browser.
  const fresh = (i: number) => `${generation}:${i}`;
  const chars = split(text);
  if (!prev) return chars.map((char, i) => ({ key: fresh(i), char }));
  const keys: (string | null)[] = chars.map(() => null);
  const old = prev.map((g) => g.char);

  // Numbers match by place value, from the right.
  if (numeric(old.join("")) && numeric(text)) {
    for (let k = 1; k <= Math.min(old.length, chars.length); k++) {
      if (old[old.length - k] === chars[chars.length - k]) keys[chars.length - k] = prev[old.length - k].key;
    }
    return chars.map((char, i) => ({ key: keys[i] ?? fresh(i), char }));
  }

  const oldWords = words(old);
  const used = new Set<number>();
  const anchors: { from: Word; to: Word }[] = [];
  for (const w of words(chars)) {
    const i = oldWords.findIndex((o, k) => !used.has(k) && o.text === w.text);
    if (i === -1) continue;
    used.add(i);
    anchors.push({ from: oldWords[i], to: w });
    for (let k = 0; k < w.end - w.start; k++) {
      if (old[oldWords[i].start + k] === chars[w.start + k]) keys[w.start + k] = prev[oldWords[i].start + k].key;
    }
  }

  const ordered = anchors.every((a, i) => i === 0 || a.from.start > anchors[i - 1].from.end);
  if (ordered) {
    const bounds = [{ from: 0, to: 0 }, ...anchors.map((a) => ({ from: a.from.end, to: a.to.end }))];
    const ends = [...anchors.map((a) => ({ from: a.from.start, to: a.to.start })), { from: old.length, to: chars.length }];
    bounds.forEach((b, g) => {
      const pairs = edges(old.slice(b.from, ends[g].from), chars.slice(b.to, ends[g].to));
      for (const [i, j] of pairs) keys[b.to + j] = prev[b.from + i].key;
    });
  }

  return chars.map((char, i) => ({ key: keys[i] ?? fresh(i), char }));
}

const NUMERIC = /^[^\p{L}]*\d[^\p{L}]*$/u;
const numeric = (text: string) => NUMERIC.test(text);

const NUMBER = /[-\u2212]?\d[\d,.]*/;

function value(text: string) {
  const match = text.match(NUMBER);
  return match ? parseFloat(match[0].replace("\u2212", "-").replace(/,/g, "")) : NaN;
}

function direction(from: string, to: string) {
  const delta = value(to) - value(from);
  return Number.isNaN(delta) ? 0 : Math.sign(delta);
}

function token(el: Element, name: string, fallback: string) {
  return getComputedStyle(el).getPropertyValue(name).trim() || fallback;
}

function ms(value: string) {
  return value.endsWith("ms") ? parseFloat(value) : parseFloat(value) * 1000;
}

function translateX(el: Element) {
  const transform = getComputedStyle(el).transform;
  return transform && transform !== "none" ? new DOMMatrixReadOnly(transform).m41 : 0;
}

function measureText(row: HTMLElement, text: string, glyphs: Glyph[]): Layout {
  const node = row.firstChild;
  const origin = row.getBoundingClientRect().left;
  const lefts = new Map<string, number>();
  let width = 0;
  if (node?.nodeType === Node.TEXT_NODE) {
    const range = document.createRange();
    let offset = 0;
    for (const g of glyphs) {
      range.setStart(node, offset);
      range.setEnd(node, (offset += g.char.length));
      const box = range.getBoundingClientRect();
      lefts.set(g.key, box.left - origin);
      width = Math.max(width, box.right - origin);
    }
  }
  return { text, glyphs, lefts, width };
}

export function TextMorph({ children, className }: { children: string; className?: string }) {
  const [shown, setShown] = useState(children);
  const [state, setState] = useState(() => ({ generation: 0, glyphs: toGlyphs(null, children, 0) }));
  if (shown !== children) {
    setShown(children);
    setState((prev) => ({ generation: prev.generation + 1, glyphs: toGlyphs(prev.glyphs, children, prev.generation + 1) }));
  }
  const { glyphs } = state;
  // Plain text until the label first changes.
  const split = state.generation > 0;
  const rowRef = useRef<HTMLSpanElement>(null);
  const ghostsRef = useRef<HTMLSpanElement>(null);
  const layout = useRef<Layout | null>(null);

  useLayoutEffect(() => {
    const row = rowRef.current;
    const ghosts = ghostsRef.current;
    if (!row || !ghosts) return;

    if (!split) {
      layout.current = measureText(row, children, glyphs);
      return;
    }

    const nodes = new Map<string, HTMLElement>();
    for (const el of row.querySelectorAll<HTMLElement>("[data-glyph]")) nodes.set(el.dataset.glyph!, el);

    const last = layout.current;
    const lefts = new Map(glyphs.map((g) => [g.key, nodes.get(g.key)!.offsetLeft]));
    const tail = nodes.get(glyphs.at(-1)?.key ?? "");
    // Fractional, like the row's own width: offsetWidth rounds, and the
    // animation would end half a pixel short and then snap.
    const width = tail ? tail.getBoundingClientRect().right - row.getBoundingClientRect().left : 0;
    layout.current = { text: children, glyphs, lefts, width };

    if (!last || last.text === children) return;
    if (matchMedia("(prefers-reduced-motion: reduce)").matches) {
      ghosts.replaceChildren();
      return;
    }

    // The glide, not the move spring: a spring's overshoot narrows a button
    // past its new width and springs it back, which reads as the control
    // settling after the click. The glide lands once.
    const spring = token(row, "--ui-ease-glide", "cubic-bezier(0.22, 1, 0.36, 1)");
    const easeExit = token(row, "--ui-ease-exit", "cubic-bezier(0.4, 0, 1, 1)");
    const duration = ms(token(row, "--ui-dur-glide", "320ms"));
    const exit = ms(token(row, "--ui-dur-instant", "150ms"));
    // Letters arrive on the plain enter curve: a spring would bounce them
    // up and down, and vertical bounce reads as jitter in a line of text.
    const enter = token(row, "--ui-ease-enter", "cubic-bezier(0.2, 1, 0.3, 1)");

    // If a previous morph is still running, start from where it visibly is.
    const running = row.getAnimations();
    const fromWidth = running.length ? row.getBoundingClientRect().width : last.width;
    running.forEach((a) => a.cancel());
    const fade = Math.min(16, Math.abs(width - fromWidth));
    row.dataset.morphing = "";
    const grow = row.animate(
      { width: [`${fromWidth}px`, `${width}px`], ["--morph-fade" as string]: [`${fade}px`, "0px"] },
      { duration, easing: spring },
    );
    grow.finished.then(
      () => delete row.dataset.morphing,
      () => {}, // cancelled by a newer morph, which owns the flag now
    );

    const dir = direction(last.text, children) || 1;
    // A small rise with a soft blur: the change reads, the line holds still.
    const enterFrom = `translateY(${0.08 * dir}em)`;
    const leaveTo = `translateY(${-0.08 * dir}em)`;

    // Arrivals wait for leaving letters to clear.
    const current = new Set(glyphs.map((g) => g.key));
    const leaving = last.glyphs.some((g) => !current.has(g.key));
    const lead = exit * (leaving ? 0.85 : 0.4);
    let entering = 0;
    for (const g of glyphs) {
      const el = nodes.get(g.key)!;
      const before = last.lefts.get(g.key);
      if (before === undefined) {
        el.animate(
          {
            opacity: [0, 1],
            transform: [enterFrom, "none"],
            filter: ["blur(2px)", "none"],
          },
          { duration: duration * 0.75, easing: enter, delay: lead + entering++ * 15, fill: "backwards" },
        );
        continue;
      }
      // FLIP from where the letter is on screen now.
      const offset = before + translateX(el) - lefts.get(g.key)!;
      el.getAnimations().forEach((a) => a.cancel());
      if (Math.abs(offset) > 0.5) {
        el.animate({ transform: [`translateX(${offset}px)`, "none"] }, { duration, easing: spring });
      }
    }

    // Ghosts live in a layer React never renders into.
    const kept = new Set(glyphs.map((g) => g.key));
    for (const g of last.glyphs) {
      if (kept.has(g.key)) continue;
      const ghost = document.createElement("span");
      ghost.className = styles.ghost;
      ghost.textContent = g.char;
      ghost.style.left = `${last.lefts.get(g.key)}px`;
      ghosts.append(ghost);
      const fade = ghost.animate(
        {
          opacity: [1, 0],
          transform: ["none", leaveTo],
          filter: ["none", "blur(2px)"],
        },
        { duration: exit, easing: easeExit, fill: "forwards" },
      );
      fade.finished.then(
        () => ghost.remove(),
        () => ghost.remove(),
      );
    }
  }, [children, glyphs, split]);

  return (
    // The letter row must run in the label's own direction.
    <span className={className ? `${styles.root} ${className}` : styles.root} dir="auto">
      <span className={styles.label}>{children}</span>
      <span ref={rowRef} className={styles.row} aria-hidden="true">
        {split
          ? glyphs.map((g) => (
              <span key={g.key} data-glyph={g.key} className={styles.glyph}>
                {g.char}
              </span>
            ))
          : children}
        <span ref={ghostsRef} className={styles.ghosts} />
      </span>
    </span>
  );
}

import type { ComponentProps, ElementType } from "react";
import styles from "./button.module.css";

// No "use client", so it renders on the server and `as` can take a server-side link.
type ButtonLinkProps = ComponentProps<"a"> & {
  variant?: "primary" | "secondary" | "ghost" | "danger";
  size?: "sm" | "md" | "lg";
  /** Your router's link component, so navigation stays client-side. Defaults to a plain <a>. */
  as?: ElementType;
};

/** A link that looks like a button, for navigation. Same variants and sizes. */
export function ButtonLink({ variant = "primary", size = "md", as: Link = "a", className, children, ...props }: ButtonLinkProps) {
  return (
    <Link
      data-variant={variant}
      data-size={size}
      className={className ? `${styles.button} ${className}` : styles.button}
      {...props}
    >
      <span className={styles.content}>{children}</span>
    </Link>
  );
}

@layer theme, base, components, utilities;

@property --button-dim {
  syntax: "<number>";
  inherits: false;
  initial-value: 1;
}

@layer components {
  .button {
    --button-bg: transparent;
    --button-bg-hover: var(--ui-fill);
    --button-bg-press: var(--ui-fill-strong);
    --button-fg: var(--ui-foreground);
    --button-edge: transparent;
    --ui-icon-stroke: var(--ui-icon-stroke-medium);

    position: relative;
    display: inline-grid;
    place-items: center;
    flex-shrink: 0;
    height: var(--ui-control-md);
    min-width: var(--ui-control-md);
    padding-inline: 20px;
    border: 0;
    border-radius: var(--ui-radius-full);
    background: none;
    color: var(--button-fg);
    isolation: isolate;
    font: var(--ui-weight-medium) var(--ui-text-md) / 1 var(--ui-font-sans);
    letter-spacing: var(--ui-tracking-control);
    white-space: nowrap;
    text-decoration: none;
    cursor: pointer;
    user-select: none;
    touch-action: manipulation;
    -webkit-tap-highlight-color: transparent;
    transition:
      color var(--ui-dur-instant) var(--ui-ease-color),
      opacity var(--ui-dur-instant) var(--ui-ease-color);
  }

  /* Fill and edge on their own layer, so a press scales the shape, not the label. */
  .button::before {
    content: "";
    position: absolute;
    inset: 0;
    z-index: -1;
    border-radius: inherit;
    background: var(--button-bg);
    box-shadow:
      inset 0 0 0 var(--ui-hairline) var(--button-edge),
      var(--button-depth, 0 0 transparent);
    transition:
      background-color var(--ui-dur-instant) var(--ui-ease-color),
      box-shadow var(--ui-dur-instant) var(--ui-ease-color),
      scale var(--ui-dur-snap) var(--ui-ease-snap);
  }

  /* Icon only (one element, named by aria-label): a capsule, not a circle,
     like every other button. */
  .button[data-icon-only] {
    width: calc(var(--ui-control-md) * var(--ui-capsule));
    padding-inline: 0;
  }

  .button[data-size="sm"][data-icon-only] {
    width: calc(var(--ui-control-sm) * var(--ui-capsule));
  }

  .button[data-size="lg"][data-icon-only] {
    width: calc(var(--ui-control-lg) * var(--ui-capsule));
  }

  .button[data-size="sm"] {
    height: var(--ui-control-sm);
    min-width: var(--ui-control-sm);
    padding-inline: 14px;
  }

  /* A small button looks 32px but takes a 40px touch: the hit area grows 4px
     above and below on touch screens, so it stays in its row's height. */
  @media (pointer: coarse) {
    .button[data-size="sm"]::after {
      content: "";
      position: absolute;
      inset: calc((var(--ui-control-sm) - var(--ui-control-md)) / 2) 0;
    }
  }

  .button[data-size="lg"] {
    height: var(--ui-control-lg);
    min-width: var(--ui-control-lg);
    padding-inline: var(--ui-space-5);
    font-size: var(--ui-text-md);
  }

  /* Hover and press mix from --button-bg and --button-fg, so overrides get
     matching shades. Filled or not, every button sits on the one control
     shadow: no glint along the top, nothing darker under the bottom edge. */
  .button[data-variant="primary"] {
    --button-depth: var(--ui-shadow-control);
    --button-bg: var(--ui-ink);
    --button-bg-hover: color-mix(in oklch, var(--button-bg) 92%, var(--button-fg));
    --button-bg-press: color-mix(in oklch, var(--button-bg) 85%, var(--button-fg));
    --button-fg: var(--ui-on-ink);
  }

  .button[data-variant="secondary"] {
    --button-bg: var(--ui-surface);
    --button-edge: var(--ui-border-strong);
    --button-depth: var(--ui-shadow-control);
  }

  .button[data-variant="danger"] {
    --button-depth: var(--ui-shadow-control);
    --button-bg: var(--ui-danger);
    --button-bg-hover: color-mix(in oklch, var(--button-bg) 93%, black);
    --button-bg-press: color-mix(in oklch, var(--button-bg) 86%, black);
    --button-fg: var(--ui-on-danger);
  }

  @media (hover: hover) {
    .button:hover:not(:disabled, [aria-busy])::before {
      background: var(--button-bg-hover);
    }
    .button[data-variant="secondary"]:hover:not(:disabled, [aria-busy])::before {
      background: var(--ui-fill-solid);
    }
  }

  .button:active:not(:disabled, [aria-busy])::before {
    --button-depth: 0 0 transparent;
    background: var(--button-bg-press);
    transition-duration: var(--ui-dur-press);
  }

  .button:active:not(:disabled, [aria-busy], [aria-haspopup])::before {
    scale: var(--ui-scale-press);
  }

  .button:focus-visible {
    outline: var(--ui-ring-focus);
    outline-offset: var(--ui-ring-offset);
  }

  .button:disabled {
    opacity: 0.5;
    cursor: default;
  }

  .button[aria-busy] {
    cursor: default;
  }

  .content {
    display: inline-flex;
    align-items: center;
    gap: var(--ui-space-2);
    /* Room for descenders inside the busy mask, cancelled by the negative margin.
       Always on, so turning busy on never moves the label. */
    margin: -4px -6px;
    padding: var(--ui-space-1) 6px;
  }

  .content svg {
    width: var(--ui-icon-md);
    height: var(--ui-icon-md);
    flex-shrink: 0;
    pointer-events: none;
  }

  /* Shown only once the work has lasted 300ms (use-delayed-busy.ts), so the
     shimmer starts at once when it does. */
  .button[data-busy-shown] .content {
    --button-dim: 1;
    mask-image: linear-gradient(
      90deg,
      rgb(0 0 0 / var(--button-dim)) 35%,
      black 50%,
      rgb(0 0 0 / var(--button-dim)) 65%
    );
    mask-size: 300% 100%;
    mask-repeat: no-repeat;
    animation:
      button-dim var(--ui-dur-base) var(--ui-ease-color) forwards,
      button-sweep var(--ui-dur-sweep) linear infinite;
  }

  @keyframes button-dim {
    to {
      --button-dim: 0.4;
    }
  }

  @keyframes button-sweep {
    from {
      mask-position: 100% 0;
    }
    to {
      mask-position: 0 0;
    }
  }

  @media (prefers-reduced-motion: reduce) {
    .button::before {
      transition-property: background-color, box-shadow;
    }
    .button:active:not(:disabled, [aria-busy], [aria-haspopup])::before {
      scale: none;
    }
    .button[data-busy-shown] .content {
      --button-dim: 0.5;
      animation: none;
    }
  }

  /* block: the full width of its container, label still centered. */
  .button[data-block] {
    display: grid;
    width: 100%;
  }
}

"use client";

import { isValidElement, type ComponentProps, type MouseEvent, type ReactNode } from "react";
import { TextMorph } from "../text-morph/text-morph";
import styles from "./button.module.css";
import { useDelayedBusy } from "./use-delayed-busy";

type ButtonProps = ComponentProps<"button"> & {
  variant?: "primary" | "secondary" | "ghost" | "danger";
  size?: "sm" | "md" | "lg";
  /** Work is in flight: presses are ignored at once, focus stays. The shimmer
   *  (and `busyLabel`) shows only once it has lasted 300ms, then for 400ms at least. */
  busy?: boolean;
  /** The label while the busy state shows, like "Saving…". Morphs from the label. */
  busyLabel?: ReactNode;
  /** Fills its container's width: the main action of a narrow form or a sheet. */
  block?: boolean;
};

export function Button({
  variant = "primary",
  size = "md",
  busy = false,
  busyLabel,
  block = false,
  type = "button",
  className,
  children,
  onClick,
  ...props
}: ButtonProps) {
  const shown = useDelayedBusy(busy);
  // One element and no text, named by aria-label: an icon button, drawn as a capsule.
  const iconOnly = isValidElement(children) && Boolean(props["aria-label"]);
  const label = shown && busyLabel !== undefined ? busyLabel : children;

  function handleClick(event: MouseEvent<HTMLButtonElement>) {
    // Busy is not disabled: the button keeps focus and its tab stop.
    if (busy) {
      event.preventDefault();
      return;
    }
    onClick?.(event);
  }

  return (
    <button
      type={type}
      data-variant={variant}
      data-size={size}
      data-block={block || undefined}
      aria-busy={busy || undefined}
      aria-disabled={busy || undefined}
      data-busy-shown={shown || undefined}
      data-icon-only={iconOnly || undefined}
      className={className ? `${styles.button} ${className}` : styles.button}
      onClick={handleClick}
      {...props}
    >
      <span className={styles.content}>
        {typeof label === "string" ? <TextMorph>{label}</TextMorph> : label}
      </span>
    </button>
  );
}

"use client";

import { useEffect, useRef, useState } from "react";

/**
 * Whether to show that work is running. Fast work never shows: the busy
 * state appears only once `busy` has lasted `delay` ms, and once it has
 * appeared it stays at least `minimum` ms, so it never flickers in and out.
 */
export function useDelayedBusy(busy: boolean, delay = 300, minimum = 400) {
  const [shown, setShown] = useState(false);
  const since = useRef(0);

  useEffect(() => {
    if (busy === shown) return;
    const wait = busy ? delay : Math.max(0, minimum - (performance.now() - since.current));
    const timer = window.setTimeout(() => {
      if (busy) since.current = performance.now();
      setShown(busy);
    }, wait);
    return () => window.clearTimeout(timer);
  }, [busy, shown, delay, minimum]);

  return shown;
}

@layer theme, base, components, utilities;

.name {
  composes: wrap from "../text/text.module.css";
}

.srOnly {
  composes: srOnly from "../text/text.module.css";
}

@layer components {
  .block {
    --block-inset: var(--ui-space-2);
    --block-action: var(--ui-control-sm);
    /* Every box's radius; also the inset plus half the action, so the corner
       and the Copy pill stay concentric. */
    --block-radius: var(--ui-radius-lg);
    position: relative;
    min-width: 0;
    border-radius: var(--block-radius);
    background: var(--ui-surface);
    /* A box at rest, like a card: the one edge and the one soft shadow. */
    box-shadow: var(--ui-shadow-resting);
    font-family: var(--ui-font-sans);
  }

  .header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: var(--ui-space-2);
    padding: var(--block-inset) var(--block-inset) var(--block-inset) var(--ui-space-5);
  }

  .name {
    color: var(--ui-muted);
    font-size: var(--ui-text-sm);
    font-weight: var(--ui-weight-medium);
    line-height: var(--ui-leading-md);
    --ui-icon-stroke: var(--ui-icon-stroke-medium);
  }

  .actions {
    display: flex;
    align-items: center;
    flex-shrink: 0;
  }

  /* Copy is plain text: no fill, no edge, no icon, quiet in the corner;
     it turns to the text color on hover. */
  .action.action {
    --button-bg: transparent;
    --button-bg-hover: transparent;
    --button-bg-press: transparent;
    padding-inline: var(--ui-space-3);
    color: var(--ui-muted);
  }

  @media (hover: hover) {
    .action.action:hover {
      color: var(--ui-foreground);
    }
  }

  @media (pointer: coarse) {
    .block {
      --block-action: var(--ui-control-md);
    }
    .action.action {
      height: var(--block-action);
    }
  }

  /* ---------- Body ---------- */

  .scroller {
    position: relative;
    overflow: auto;
    overscroll-behavior-x: contain;
    border-radius: 0 0 var(--block-radius) var(--block-radius);
    scrollbar-width: thin;
    scrollbar-color: var(--ui-border-strong) transparent;
  }

  .scroller:focus-visible {
    outline: none;
  }

  /* Ring on the block: on the scroller the edge-fade mask would hide it. */
  .block:has(.scroller:focus-visible) {
    outline: var(--ui-ring-focus);
    outline-offset: var(--ui-ring-offset);
  }

  .scroller[data-fade-end] {
    mask-image: linear-gradient(to left, transparent, black var(--ui-space-6));
  }

  .scroller[data-fade-start] {
    mask-image: linear-gradient(to right, transparent, black var(--ui-space-6));
  }

  .scroller[data-fade-start][data-fade-end] {
    mask-image: linear-gradient(
      to right,
      transparent,
      black var(--ui-space-6),
      black calc(100% - var(--ui-space-6)),
      transparent
    );
  }

  .pre {
    /* Keeps the right padding when scrolled. */
    width: max-content;
    min-width: 100%;
    margin: 0;
    padding: var(--ui-space-1) var(--ui-space-5) var(--ui-space-5);
    counter-reset: line;
  }

  .code {
    display: block;
    color: var(--ui-foreground);
    font-family: var(--ui-font-mono);
    font-size: var(--ui-text-sm);
    line-height: var(--ui-leading-md);
    tab-size: 2;
    white-space: pre;
  }

  .line {
    display: block;
    min-height: 1lh;
  }

  /* Numbers are generated content so copying the code never picks them up. */
  .pre[data-numbers] .line {
    display: grid;
    grid-template-columns: calc(var(--digits) * 1ch) minmax(0, 1fr);
    column-gap: var(--ui-space-4);
  }

  .pre[data-numbers] .line::before {
    content: counter(line);
    counter-increment: line;
    color: var(--ui-subtle);
    font-variant-numeric: tabular-nums;
    text-align: end;
    user-select: none;
  }

  .pre[data-numbers] .line {
    grid-template-columns: calc(var(--digits) * 1ch) max-content;
  }

  /* ---------- Tokens ---------- */

  /* Four quiet hues from the accent and status text roles, the rest in the
     text grays. Keywords, strings, numbers and types carry the color; names
     (functions, properties) stay in the text color, so a block reads as text
     with a few marks rather than a rainbow. Mixes with the foreground go
     through oklab, so the gray adds no hue of its own; the one hue-to-hue mix
     goes through oklch, so blue and red meet at violet. 30-40% foreground in
     each keeps them calm and above 4.5:1 in both themes. */
  .block {
    --code-keyword: color-mix(in oklab, var(--ui-accent-text) 65%, var(--ui-foreground));
    --code-control: var(--code-keyword);
    --code-string: color-mix(in oklab, var(--ui-success-text) 65%, var(--ui-foreground));
    --code-number: color-mix(in oklab, var(--ui-warning-text) 70%, var(--ui-foreground));
    --code-function: var(--ui-foreground);
    --code-type: color-mix(
      in oklab,
      color-mix(in oklch, var(--ui-danger-text) 60%, var(--ui-accent-text)) 60%,
      var(--ui-foreground)
    );
    --code-attr: color-mix(in oklab, var(--ui-accent-text) 35%, var(--ui-foreground));
    --code-property: var(--ui-foreground);
    --code-punctuation: var(--ui-muted);
    --code-comment: var(--ui-subtle);
  }

  .keyword {
    color: var(--code-keyword);
  }

  .control {
    color: var(--code-control);
  }

  .string {
    color: var(--code-string);
  }

  .number,
  .literal,
  .value {
    color: var(--code-number);
  }

  .function {
    color: var(--code-function);
  }

  .type,
  .tag,
  .selector {
    color: var(--code-type);
  }

  .attr,
  .variable {
    color: var(--code-attr);
  }

  .property,
  .key {
    color: var(--code-property);
  }

  .punctuation {
    color: var(--code-punctuation);
  }

  .comment {
    color: var(--code-comment);
  }

  /* ---------- Streaming ---------- */

  .block[aria-busy] .line > span > span {
    animation: code-in var(--ui-dur-base) var(--ui-ease-enter) backwards;
  }

  @keyframes code-in {
    from {
      opacity: 0;
    }
  }

  @media (prefers-reduced-motion: reduce) {
    .block[aria-busy] .line > span > span {
      animation: none;
    }
  }
}

"use client";

import {
  memo,
  useCallback,
  useEffect,
  useLayoutEffect,
  useMemo,
  useRef,
  useState,
  type CSSProperties,
} from "react";
import { Button } from "../button/button";
import { canTokenize, tokenizeLine, type LineState, type Token } from "./tokenize";
import styles from "./code-block.module.css";

export { tokenizeLine, canTokenize } from "./tokenize";
export type { Token, TokenType, LineState } from "./tokenize";

const LANGUAGE_NAMES: Record<string, string> = {
  ts: "TypeScript", tsx: "TSX", typescript: "TypeScript",
  js: "JavaScript", jsx: "JSX", javascript: "JavaScript", mjs: "JavaScript", cjs: "JavaScript",
  py: "Python", python: "Python",
  sh: "Shell", bash: "Bash", shell: "Shell", zsh: "Zsh", console: "Terminal",
  json: "JSON", jsonc: "JSON",
  css: "CSS",
};

type CodeBlockProps = {
  /** The source. While streaming, pass the text so far; only append. */
  code: string;
  /** `ts`, `py`, `sh`, `json`… */
  language?: string;
  /** Header text instead of the language name, e.g. a file name. */
  title?: string;
  lineNumbers?: boolean;
  /** Text is still arriving; sets `aria-busy`. */
  streaming?: boolean;
  /** Use the built-in tokenizer when the language is supported. */
  highlight?: boolean;
  /** Trusted HTML per line from your highlighter; same lines as `code`. */
  lineHtml?: string[];
  maxHeight?: CSSProperties["maxHeight"];
  className?: string;
};

// Stable token arrays let memoized lines skip re-rendering.
const tokenCache = new Map<string, { tokens: Token[]; state: LineState }>();

function cachedTokens(text: string, language: string, state: LineState) {
  const key = `${language}\u0000${state}\u0000${text}`;
  let hit = tokenCache.get(key);
  if (!hit) {
    if (tokenCache.size > 5000) tokenCache.clear();
    hit = tokenizeLine(text, language, state);
    tokenCache.set(key, hit);
  }
  return hit;
}

type CopyState = "idle" | "copied" | "failed";

export function CodeBlock({
  code,
  language,
  title,
  lineNumbers = false,
  streaming = false,
  highlight = true,
  lineHtml,
  maxHeight,
  className,
}: CodeBlockProps) {
  const [copy, setCopy] = useState<CopyState>("idle");
  const [overflow, setOverflow] = useState({ start: false, end: false, y: false });
  const scrollerRef = useRef<HTMLDivElement>(null);
  const atBottom = useRef(true);
  const copyTimer = useRef(0);

  const name = title ?? (language ? (LANGUAGE_NAMES[language.toLowerCase()] ?? language) : "Code");
  // While streaming, show only whole words.
  const shown = streaming ? code.slice(0, code.search(/\s\S*$/) + 1) : code;
  const lines = useMemo(() => shown.split("\n"), [shown]);
  const tokenize = highlight && !lineHtml && canTokenize(language);

  const lineTokens = useMemo(() => {
    if (!tokenize) return null;
    let state: LineState = "";
    return lines.map((text, i) => {
      // Not cached: the last line is still being written.
      const hit = i < lines.length - 1 ? cachedTokens(text, language!, state) : tokenizeLine(text, language!, state);
      state = hit.state;
      return hit.tokens;
    });
  }, [tokenize, lines, language]);

  const measure = useCallback(() => {
    const el = scrollerRef.current;
    if (!el) return;
    const max = el.scrollWidth - el.clientWidth;
    const left = Math.abs(el.scrollLeft);
    const next = { start: left > 1, end: max - left > 1, y: el.scrollHeight - el.clientHeight > 1 };
    atBottom.current = el.scrollHeight - el.scrollTop - el.clientHeight < 8;
    setOverflow((prev) => (prev.start === next.start && prev.end === next.end && prev.y === next.y ? prev : next));
  }, []);

  useEffect(() => {
    const el = scrollerRef.current;
    if (!el) return;
    const observer = new ResizeObserver(measure);
    observer.observe(el);
    if (el.firstElementChild) observer.observe(el.firstElementChild);
    return () => observer.disconnect();
  }, [measure]);

  useLayoutEffect(() => {
    const el = scrollerRef.current;
    if (el && maxHeight !== undefined && streaming && atBottom.current) el.scrollTop = el.scrollHeight;
  }, [code, maxHeight, streaming]);

  useEffect(() => () => clearTimeout(copyTimer.current), []);

  async function handleCopy() {
    clearTimeout(copyTimer.current);
    try {
      if (!navigator.clipboard) throw new Error("Clipboard unavailable");
      await navigator.clipboard.writeText(code);
      setCopy("copied");
    } catch {
      setCopy("failed");
    }
    copyTimer.current = window.setTimeout(() => setCopy("idle"), 2000);
  }

  // Code never wraps: a long line scrolls sideways, so indentation and
  // columns read as written.
  const scrollable = overflow.start || overflow.end || overflow.y;
  const digits = String(lines.length).length;

  return (
    <div className={className ? `${styles.block} ${className}` : styles.block} aria-busy={streaming || undefined}>
      <div className={styles.header}>
        <span className={styles.name} title={name}>
          {name}
        </span>
        <div className={styles.actions}>
          <Button variant="ghost" size="sm" className={styles.action} onClick={handleCopy} aria-label={`Copy ${name} code`}>
            {/* A plain string: Button morphs it itself, and a lone element
                child with an aria-label would draw an icon-only capsule. */}
            {copy === "copied" ? "Copied" : copy === "failed" ? "Copy failed" : "Copy"}
          </Button>
          <span role="status" className={styles.srOnly}>
            {copy === "copied" ? "Copied to clipboard" : copy === "failed" ? "Couldn’t copy. Select the code and copy it manually." : ""}
          </span>
        </div>
      </div>

      <div
        ref={scrollerRef}
        className={styles.scroller}
        data-fade-start={overflow.start || undefined}
        data-fade-end={overflow.end || undefined}
        style={{ maxHeight }}
        onScroll={measure}
        // Focusable only when scrollable, so the keyboard can scroll it.
        tabIndex={scrollable ? 0 : undefined}
        role={scrollable ? "region" : undefined}
        aria-label={scrollable ? `${name} code` : undefined}
      >
        <pre className={styles.pre} data-numbers={lineNumbers || undefined} style={{ "--digits": digits } as CSSProperties}>
          <code className={styles.code}>
            {lines.map((text, i) => (
              <Line
                key={i}
                text={text}
                tokens={lineTokens?.[i]}
                html={lineHtml?.[i]}
                live={streaming && i === lines.length - 1}
              />
            ))}
          </code>
        </pre>
      </div>
    </div>
  );
}

type LineProps = { text: string; tokens?: Token[]; html?: string; live: boolean };

// Per-word spans keyed by offset, so each word fades in once.
const WORD = /\S+\s*|\s+/g;

const Line = memo(function Line({ text, tokens, html, live }: LineProps) {
  let offset = 0;
  const words = (t: Token) => {
    const from = offset;
    offset += t.text.length;
    return Array.from(t.text.matchAll(WORD), (m) => (
      <span key={from + m.index} className={t.type === "plain" ? undefined : styles[t.type]}>
        {m[0]}
      </span>
    ));
  };
  return (
    <span className={styles.line}>
      <span>
        {html !== undefined ? (
          <span dangerouslySetInnerHTML={{ __html: html }} />
        ) : tokens && live ? (
          tokens.flatMap(words)
        ) : tokens ? (
          tokens.map((t, i) =>
            t.type === "plain" ? (
              t.text
            ) : (
              <span key={i} className={styles[t.type]}>
                {t.text}
              </span>
            ),
          )
        ) : (
          text
        )}
      </span>
    </span>
  );
});

/** A small line tokenizer. A line's tokens depend only on its text and start state. */

/**
 * - `keyword`: declarations and operators (`const`, `import`, `typeof`); CSS pseudo-classes.
 * - `control`: flow (`if`, `return`, `await`); CSS at-rules; shell `if`, `then`.
 * - `literal`: `true`, `false`, `null`, `undefined`, `this`; Python `None`, `self`.
 * - `function`: a name that's called or declared as one; a shell command; a CSS function.
 * - `type`: PascalCase names, primitive types after `:`, names after `class`, `new`, `extends`.
 * - `property`: a name after `.`, or an object key.
 * - `tag` / `attr`: JSX tag and attribute names; CSS element selectors and `[attr]`; shell flags are `attr`.
 * - `selector`: CSS `.class` and `#id`.
 * - `variable`: shell `$VAR`; CSS custom properties.
 * - `key`: a JSON key or a CSS property name. `value`: a word in a CSS value.
 * - `punctuation`: brackets, operators, separators.
 */
export type TokenType =
  | "plain"
  | "keyword"
  | "control"
  | "string"
  | "comment"
  | "number"
  | "literal"
  | "function"
  | "type"
  | "property"
  | "tag"
  | "attr"
  | "selector"
  | "variable"
  | "key"
  | "value"
  | "punctuation";
export type Token = { type: TokenType; text: string };
/**
 * Carried from one line to the next. `""` means nothing is open. `jsx:…` is
 * the stack of open JSX tags, children and `{…}` expressions; `sh-args`
 * follows a shell line that ended in `\`; `css-value` a CSS value that runs
 * onto the next line.
 */
export type LineState =
  | ""
  | "block-comment"
  | "template"
  | 'triple"'
  | "triple'"
  | "sh-args"
  | "css-value"
  | `jsx:${string}`;

type Family = "js" | "py" | "sh" | "json" | "css";

const FAMILIES: Record<string, Family> = {
  js: "js", jsx: "js", javascript: "js", mjs: "js", cjs: "js",
  ts: "js", tsx: "js", typescript: "js",
  py: "py", python: "py",
  sh: "sh", bash: "sh", shell: "sh", zsh: "sh", console: "sh",
  json: "json", jsonc: "json",
  css: "css",
};

/** Languages whose `<Name` can open a JSX tag. Plain TS has generics there instead. */
const JSX = new Set(["js", "jsx", "javascript", "mjs", "cjs", "tsx"]);

const words = (list: string) => new Set(list.split(" "));

const JS_KEYWORDS = words(
  "class const default delete enum export extends function implements import in instanceof interface keyof let new private protected public typeof var void",
);
/** Keywords only when followed by a name, so `item.type` and `const from = 1` stay plain. */
const JS_CONTEXTUAL = words(
  "abstract accessor as asserts async declare from get infer is module namespace of override readonly satisfies set static type unique",
);
const JS_CONTROL = words(
  "await break case catch continue debugger do else finally for if return switch throw try while with yield",
);
const JS_LITERALS = words("true false null undefined this super NaN Infinity");
const JS_PRIMITIVES = words("string number boolean any unknown never object bigint symbol");
/** The name after one of these is a type. */
const JS_TYPE_INTRO = words("class interface type enum extends implements new namespace keyof typeof satisfies as is");

const PY_KEYWORDS = words("and as class def del from global import in is lambda nonlocal not or pass async");
const PY_CONTROL = words(
  "assert await break case continue elif else except finally for if match raise return try while with yield",
);
const PY_LITERALS = words("True False None self cls");

const SH_CONTROL = words("if then else elif fi for while until do done case esac function in select return");
/** These run the command that follows them. */
const SH_PREFIX = words("sudo time exec command env nohup xargs");

/** Whether `language` has a tokenizer. */
export function canTokenize(language: string | undefined) {
  return !!language && language.toLowerCase() in FAMILIES;
}

const NUMBER = /^(?:0[xX][\da-fA-F_]+|0[bB][01_]+|(?:\d[\d_]*\.?[\d_]*|\.\d[\d_]*)(?:[eE][+-]?\d+)?n?)/;
const WORD = /^[A-Za-z_$][\w$]*/;
// Hyphens included, so `--ui-space-3` is one word and its 3 isn't a number.
const CSS_WORD = /^-{0,2}[A-Za-z_][\w-]*/;
const CSS_UNIT = /^(?:%|[a-zA-Z]+)/;
const PUNCT = /^(?:=>|\?\?=?|\?\.|\.\.\.|[=!]==?|[<>]=?|&&=?|\|\|=?|\*\*|[-+*/%&|^~!?:;,.(){}[\]<>=@#\\])/;
const PASCAL = /^[A-Z](?:[\w$]*[a-z][\w$]*)?$/;

export function tokenizeLine(line: string, language: string, state: LineState = ""): { tokens: Token[]; state: LineState } {
  const lang = language.toLowerCase();
  const family = FAMILIES[lang];
  if (!family) return { tokens: [{ type: "plain", text: line }], state: "" };

  const tokens: Token[] = [];
  const push = (type: TokenType, text: string) => {
    if (!text) return;
    const last = tokens.at(-1);
    if (last && last.type === type) last.text += text;
    else tokens.push({ type, text });
  };
  const emit = (inner: Token[]) => inner.forEach((t) => push(t.type, t.text));

  if (family === "css") return { tokens, state: css(line, state, push) };
  if (family === "sh") return shell(line, lang, state, tokens, push);

  let i = 0;
  // Open JSX contexts: "t" in a tag, "x" in children, "e<n>" in a {…} expression n braces deep.
  const stack: string[] = state.startsWith("jsx:") ? state.slice(4).split(",") : [];
  const jsx = family === "js" && JSX.has(lang);

  if (state === "block-comment" || state === 'triple"' || state === "triple'") {
    const close = state === "block-comment" ? "*/" : state === 'triple"' ? '"""' : "'''";
    const end = findClose(line, 0, close, state !== "block-comment");
    const type = state === "block-comment" ? "comment" : "string";
    if (end === -1) {
      push(type, line);
      return { tokens, state };
    }
    push(type, line.slice(0, end));
    i = end;
  } else if (state === "template") {
    const end = template(line, 0, lang, push, emit);
    if (end === -1) return { tokens, state };
    i = end;
  }

  while (i < line.length) {
    const rest = line.slice(i);
    const ch = line[i];
    const prev = i > 0 ? line[i - 1] : "";
    const frame = stack.at(-1);

    // ---------- JSX ----------
    if (frame === "x" || frame === "t" || (jsx && ch === "<" && jsxStarts(line, i))) {
      const close = /^<\/\s*([A-Za-z][\w.:-]*)?\s*>/.exec(rest);
      if (ch === "<" && close) {
        const name = close[1] ?? "";
        const at = close[0].indexOf(name, 2);
        push("punctuation", close[0].slice(0, name ? at : close[0].length - 1));
        push("tag", name);
        push("punctuation", name ? close[0].slice(at + name.length) : ">");
        if (stack.at(-1) === "x") stack.pop();
        i += close[0].length;
        continue;
      }
      const open = /^<([A-Za-z][\w.:-]*)?/.exec(rest);
      if (ch === "<" && open && (open[1] || line[i + 1] === ">")) {
        push("punctuation", "<");
        if (open[1]) {
          push("tag", open[1]);
          stack.push("t");
          i += open[0].length;
        } else {
          push("punctuation", ">");
          stack.push("x");
          i += 2;
        }
        continue;
      }
      if (frame === "x") {
        if (ch === "{") {
          push("punctuation", ch);
          stack.push("e1");
          i++;
          continue;
        }
        const text = /^[^<{]+/.exec(rest)?.[0] ?? ch;
        push("plain", text);
        i += text.length;
        continue;
      }
      if (frame === "t") {
        if (rest.startsWith("/>")) {
          push("punctuation", "/>");
          stack.pop();
          i += 2;
          continue;
        }
        if (ch === ">") {
          push("punctuation", ch);
          stack[stack.length - 1] = "x";
          i++;
          continue;
        }
        if (ch === "{") {
          push("punctuation", ch);
          stack.push("e1");
          i++;
          continue;
        }
        if (ch === '"' || ch === "'") {
          const end = findClose(line, i + 1, ch, false);
          const stop = end === -1 ? line.length : end;
          push("string", line.slice(i, stop));
          i = stop;
          continue;
        }
        const attr = /^[A-Za-z_$][\w$:.-]*/.exec(rest);
        if (attr) {
          push("attr", attr[0]);
          i += attr[0].length;
          continue;
        }
        push(/\s/.test(ch) ? "plain" : "punctuation", ch);
        i++;
        continue;
      }
    }

    // A {…} expression inside JSX ends at its matching brace.
    if (frame?.startsWith("e") && (ch === "{" || ch === "}")) {
      const depth = Number(frame.slice(1)) + (ch === "{" ? 1 : -1);
      if (depth === 0) stack.pop();
      else stack[stack.length - 1] = `e${depth}`;
      push("punctuation", ch);
      i++;
      continue;
    }

    // ---------- Comments ----------
    if ((family === "js" || family === "json") && rest.startsWith("//")) {
      push("comment", rest);
      break;
    }
    if ((family === "js" || family === "json") && rest.startsWith("/*")) {
      const end = findClose(line, i + 2, "*/", false);
      if (end === -1) {
        push("comment", rest);
        return { tokens, state: "block-comment" };
      }
      push("comment", line.slice(i, end));
      i = end;
      continue;
    }
    if (family === "py" && ch === "#") {
      push("comment", rest);
      break;
    }

    // ---------- Strings ----------
    if (family === "py" && (rest.startsWith('"""') || rest.startsWith("'''"))) {
      const quote = rest.slice(0, 3);
      const end = findClose(line, i + 3, quote, true);
      if (end === -1) {
        push("string", rest);
        return { tokens, state: quote === '"""' ? 'triple"' : "triple'" };
      }
      push("string", line.slice(i, end));
      i = end;
      continue;
    }
    if (ch === "`" && family === "js") {
      push("string", "`");
      const end = template(line, i + 1, lang, push, emit);
      if (end === -1) return { tokens, state: "template" };
      i = end;
      continue;
    }
    if (ch === '"' || (ch === "'" && family !== "json")) {
      let end = findClose(line, i + 1, ch, true);
      if (end === -1) end = line.length;
      const isKey = family === "json" && /^\s*:/.test(line.slice(end));
      push(isKey ? "key" : "string", line.slice(i, end));
      i = end;
      continue;
    }

    // ---------- Numbers ----------
    if (/[\d.]/.test(ch) && !/[\w$]/.test(prev)) {
      const match = NUMBER.exec(rest);
      if (match && match[0] !== ".") {
        push("number", match[0]);
        i += match[0].length;
        continue;
      }
    }

    // ---------- Words ----------
    if (family === "py" && ch === "@" && WORD.test(line.slice(i + 1)) && !line.slice(0, i).trim()) {
      const name = WORD.exec(line.slice(i + 1))![0];
      push("function", "@" + name);
      i += name.length + 1;
      continue;
    }
    const word = WORD.exec(rest);
    if (word) {
      const w = word[0];
      const after = line.slice(i + w.length);
      push(family === "js" ? jsWord(w, line, i, after) : family === "py" ? pyWord(w, line, i, after) : jsonWord(w), w);
      i += w.length;
      continue;
    }

    const punct = PUNCT.exec(rest);
    if (punct) {
      push("punctuation", punct[0]);
      i += punct[0].length;
      continue;
    }
    push("plain", ch);
    i++;
  }

  return { tokens, state: stack.length ? `jsx:${stack.join(",")}` : "" };
}

/** The last non-space character before `i`, or `""` at the start of the line. */
function before(line: string, i: number) {
  return /(\S)\s*$/.exec(line.slice(0, i))?.[1] ?? "";
}

/** The word just before `i`, skipping spaces. */
function wordBefore(line: string, i: number) {
  return /([A-Za-z_$][\w$]*)\s*$/.exec(line.slice(0, i))?.[1] ?? "";
}

/** `<` opens JSX where an expression can start: after `(`, `=`, `return`, `&&`, `?`… or at a line's start. */
function jsxStarts(line: string, i: number) {
  if (!/[A-Za-z>]/.test(line[i + 1] ?? "")) return false;
  const b = before(line, i);
  if (!b || "([{,;=?:&|>!}".includes(b)) return true;
  return /\b(?:return|yield|default|case)$/.test(line.slice(0, i).trimEnd());
}

function jsWord(w: string, line: string, i: number, after: string): TokenType {
  const b = before(line, i);
  const called = /^\s*(?:\?\.)?\(/.test(after) || /^<[\w\s,.[\]|&]*>\(/.test(after);
  if (b === "." && line[i - 1] === ".") {
    if (called) return "function";
    return PASCAL.test(w) ? "type" : "property";
  }
  if (b === "." && line.slice(i - 2, i) === "?.") return called ? "function" : "property";
  // An object or type-literal key: `{ kind: "fee" }`, `onSend?: () => void`.
  if (/^\??:(?!:)/.test(after.trimStart()) && (!b || "{,;".includes(b)) && !JS_CONTROL.has(w) && w !== "default") {
    return "property";
  }
  if (JS_LITERALS.has(w)) return "literal";
  if (JS_CONTROL.has(w)) return "control";
  if (JS_KEYWORDS.has(w)) return "keyword";
  if (JS_CONTEXTUAL.has(w) && /^\s+[\w$*{["'`]/.test(after) && !/^\s+(?:in|of|instanceof)\b/.test(after)) {
    return "keyword";
  }
  const prevWord = b && /[\w$]/.test(b) ? wordBefore(line, i) : "";
  if (JS_TYPE_INTRO.has(prevWord) && prevWord !== "type") return PASCAL.test(w) || prevWord !== "new" ? "type" : "plain";
  if (prevWord === "type" && /^\s*[=<]/.test(after)) return "type";
  if (called) return prevWord === "new" ? "type" : "function";
  if (prevWord === "function") return "function";
  if (PASCAL.test(w)) return "type";
  if (JS_PRIMITIVES.has(w) && (":|&<,=([".includes(b) || prevWord === "keyof" || prevWord === "extends")) return "type";
  return "plain";
}

function pyWord(w: string, line: string, i: number, after: string): TokenType {
  const b = before(line, i);
  const called = /^\s*\(/.test(after);
  if (b === "." && line[i - 1] === ".") return called ? "function" : PASCAL.test(w) ? "type" : "property";
  if (PY_LITERALS.has(w)) return "literal";
  if (PY_CONTROL.has(w)) return "control";
  if (PY_KEYWORDS.has(w)) return "keyword";
  const prevWord = b && /\w/.test(b) ? wordBefore(line, i) : "";
  if (prevWord === "def") return "function";
  if (prevWord === "class") return "type";
  if (called) return PASCAL.test(w) ? "type" : "function";
  if (PASCAL.test(w)) return "type";
  return "plain";
}

function jsonWord(w: string): TokenType {
  return w === "true" || w === "false" || w === "null" ? "literal" : "plain";
}

/**
 * Pushes a template literal's body from `from`, with `${…}` tokenized as
 * code. Returns the index past the closing backtick, or -1 if the line ends
 * first (an interpolation that runs past the line stays string-colored).
 */
function template(
  line: string,
  from: number,
  lang: string,
  push: (type: TokenType, text: string) => void,
  emit: (tokens: Token[]) => void,
) {
  let start = from;
  for (let j = from; j < line.length; j++) {
    if (line[j] === "\\") {
      j++;
      continue;
    }
    if (line[j] === "`") {
      push("string", line.slice(start, j + 1));
      return j + 1;
    }
    if (line.startsWith("${", j)) {
      const end = matchBrace(line, j + 2);
      if (end === -1) break;
      push("string", line.slice(start, j));
      push("punctuation", "${");
      // `ts` so a `<` inside isn't read as JSX.
      emit(tokenizeLine(line.slice(j + 2, end), lang === "tsx" || lang === "jsx" ? "ts" : lang).tokens);
      push("punctuation", "}");
      j = end;
      start = end + 1;
    }
  }
  push("string", line.slice(start));
  return -1;
}

/** Index of the `}` that closes a brace opened just before `from`, skipping strings. -1 if none on the line. */
function matchBrace(line: string, from: number) {
  let depth = 1;
  for (let j = from; j < line.length; j++) {
    const c = line[j];
    if (c === '"' || c === "'" || c === "`") {
      const end = findClose(line, j + 1, c, true);
      if (end === -1) return -1;
      j = end - 1;
    } else if (c === "{") depth++;
    else if (c === "}" && --depth === 0) return j;
  }
  return -1;
}

// ---------- Shell ----------

function shell(
  line: string,
  lang: string,
  state: LineState,
  tokens: Token[],
  push: (type: TokenType, text: string) => void,
): { tokens: Token[]; state: LineState } {
  let i = 0;
  let command = state !== "sh-args";
  if (lang === "console" && state !== "sh-args") {
    // Only prompt lines are commands; the rest is output.
    const prompt = /^\s*[$>]\s/.exec(line);
    if (!prompt) {
      push("plain", line);
      return { tokens, state: "" };
    }
    push("punctuation", prompt[0]);
    i = prompt[0].length;
  }

  while (i < line.length) {
    const rest = line.slice(i);
    const ch = line[i];
    const prev = i > 0 ? line[i - 1] : "";

    if (/\s/.test(ch)) {
      const space = /^\s+/.exec(rest)![0];
      push("plain", space);
      i += space.length;
      continue;
    }
    if (ch === "#" && (i === 0 || /\s/.test(prev))) {
      push("comment", rest);
      break;
    }
    if (rest === "\\") {
      push("punctuation", ch);
      return { tokens, state: "sh-args" };
    }
    if (ch === '"' || ch === "'") {
      // Single quotes have no escapes.
      let end = findClose(line, i + 1, ch, ch === '"');
      if (end === -1) end = line.length;
      push("string", line.slice(i, end));
      i = end;
      continue;
    }
    const variable = /^\$(?:\{[^}]*\}|[A-Za-z_]\w*|[\d#?@*$!-])/.exec(rest);
    if (variable) {
      push("variable", variable[0]);
      i += variable[0].length;
      continue;
    }
    const op = /^(?:\$\(|&&|\|\||[|;()&]|\d?>>?&?\d?|<)/.exec(rest);
    if (op) {
      push("punctuation", op[0]);
      i += op[0].length;
      if (!/[<>]/.test(op[0])) command = true;
      continue;
    }
    const word = /^[^\s|&;()<>'"`$]+/.exec(rest)?.[0] ?? ch;
    i += word.length;
    if (command) {
      const assign = /^([A-Za-z_]\w*)=(.*)$/.exec(word);
      if (assign) {
        push("variable", assign[1]);
        push("punctuation", "=");
        push("plain", assign[2]);
      } else if (SH_CONTROL.has(word)) {
        push("control", word);
        command = !/^(?:for|case|select|function|in)$/.test(word);
      } else {
        push("function", word);
        command = SH_PREFIX.has(word);
      }
    } else if (word.startsWith("-") && word.length > 1 && !/^-\d/.test(word)) {
      const eq = word.indexOf("=");
      push("attr", eq === -1 ? word : word.slice(0, eq));
      if (eq !== -1) {
        push("punctuation", "=");
        push("plain", word.slice(eq + 1));
      }
    } else if (SH_CONTROL.has(word) && word === "in") {
      push("control", word);
    } else {
      push(/^-?\d+(?:\.\d+)?$/.test(word) ? "number" : "plain", word);
    }
  }
  return { tokens, state: "" };
}

// ---------- CSS ----------

/** Pushes a CSS line's tokens and returns the state it leaves open. */
function css(line: string, state: LineState, push: (type: TokenType, text: string) => void): LineState {
  let i = 0;
  if (state === "block-comment") {
    const end = findClose(line, 0, "*/", false);
    push("comment", end === -1 ? line : line.slice(0, end));
    if (end === -1) return state;
    i = end;
  }
  type Mode = "selector" | "value" | "prelude" | "start";
  // Before its first `{`, a line is a selector if it opens a block or lists
  // selectors (`a,`); otherwise it starts as declarations.
  const code = line.replace(/\/\*.*?(\*\/|$)/g, "");
  let selectorLine = state !== "css-value" && (/\{/.test(code) || (/,\s*$/.test(code) && !/:\s/.test(code)));
  let mode: Mode = state === "css-value" ? "value" : "start";
  let parens = 0;

  while (i < line.length) {
    const rest = line.slice(i);
    const ch = line[i];
    const prev = i > 0 ? line[i - 1] : "";

    if (rest.startsWith("/*")) {
      const end = findClose(line, i + 2, "*/", false);
      push("comment", end === -1 ? rest : line.slice(i, end));
      if (end === -1) return "block-comment";
      i = end;
      continue;
    }
    if (/\s/.test(ch)) {
      const space = /^\s+/.exec(rest)![0];
      push("plain", space);
      i += space.length;
      continue;
    }
    if (ch === '"' || ch === "'") {
      let end = findClose(line, i + 1, ch, true);
      if (end === -1) end = line.length;
      push("string", line.slice(i, end));
      i = end;
      continue;
    }
    if (ch === "{" || ch === "}" || ch === ";") {
      push("punctuation", ch);
      mode = "start";
      selectorLine = false;
      parens = 0;
      i++;
      continue;
    }
    const at = /^(?:@[\w-]+|!important\b)/.exec(rest);
    if (at) {
      push(at[0].startsWith("@") ? "control" : "keyword", at[0]);
      if (at[0].startsWith("@")) mode = "prelude";
      i += at[0].length;
      continue;
    }

    if (mode === "start" && (selectorLine || /^[^:;]*\{/.test(rest))) mode = "selector";

    if (mode === "selector") {
      const sel = /^(?:[.#][\w-]+|::?[\w-]+|&|\*)/.exec(rest);
      if (sel) {
        const s = sel[0];
        push(s[0] === ":" ? "keyword" : s === "&" || s === "*" ? "tag" : "selector", s);
        i += s.length;
        continue;
      }
      const attr = /^\[\s*([\w-]+)/.exec(rest);
      if (attr) {
        push("punctuation", attr[0].slice(0, attr[0].length - attr[1].length));
        push("attr", attr[1]);
        i += attr[0].length;
        continue;
      }
      const el = CSS_WORD.exec(rest);
      if (el) {
        push(/^(?:from|to)$/.test(el[0]) ? "keyword" : "tag", el[0]);
        i += el[0].length;
        continue;
      }
      push("punctuation", ch);
      i++;
      continue;
    }

    // Declarations, values and at-rule preludes.
    if (ch === "#" && mode === "value") {
      const hex = /^#[\da-fA-F]{3,8}\b/.exec(rest);
      if (hex) {
        push("number", hex[0]);
        i += hex[0].length;
        continue;
      }
    }
    const minus = ch === "-" && /[\d.]/.test(line[i + 1] ?? "") && !/[\w)-]/.test(prev);
    if ((minus || /[\d.]/.test(ch)) && !/[\w-]/.test(prev)) {
      const match = NUMBER.exec(minus ? rest.slice(1) : rest);
      if (match && match[0] !== ".") {
        const sign = minus ? "-" : "";
        const unit = CSS_UNIT.exec(rest.slice(sign.length + match[0].length))?.[0] ?? "";
        push("number", sign + match[0] + unit);
        i += sign.length + match[0].length + unit.length;
        continue;
      }
    }
    const name = CSS_WORD.exec(rest);
    if (name) {
      const n = name[0];
      const after = line.slice(i + n.length);
      if (mode === "start" && /^\s*:/.test(after)) {
        push(n.startsWith("--") ? "variable" : "key", n);
        const colon = after.indexOf(":") + 1;
        push("punctuation", after.slice(0, colon));
        i += n.length + colon;
        mode = "value";
        continue;
      }
      if (mode === "prelude" && parens > 0 && /^\s*:/.test(after)) push("key", n);
      else if (after.startsWith("(")) push("function", n);
      else if (n.startsWith("--")) push("variable", n);
      else if (mode === "prelude" && /^(?:and|or|not|only)$/.test(n)) push("keyword", n);
      else push("value", n);
      i += n.length;
      continue;
    }
    if (ch === "(") parens++;
    if (ch === ")") parens = Math.max(0, parens - 1);
    push("punctuation", ch);
    i++;
  }
  return mode === "value" ? "css-value" : "";
}

/** Index just past `close`, skipping backslash escapes. -1 if the line ends first. */
function findClose(line: string, from: number, close: string, escapes: boolean) {
  for (let i = from; i < line.length; i++) {
    if (escapes && line[i] === "\\") {
      i++;
      continue;
    }
    if (line.startsWith(close, i)) return i + close.length;
  }
  return -1;
}
